def removeDuplicates(nums):
    res = []
    for x in nums:
        if res.count(x) < 2:
            res.append(x)
    for i in range(len(res)): nums[i] = res[i]
    return len(res)

reference_solutions.optimal_python:
def removeDuplicates(nums):
    if len(nums) <= 2:
        return len(nums)
    write = 2
    for i in range(2, len(nums)):
        if nums[i] != nums[write - 2]:
            nums[write] = nums[i]
            write += 1
    return write

